argv:
$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
Add-Type -AssemblyName System.Windows.Forms
Add-Type @"
using System;
using System.Runtime.InteropServices;
public static class W32Probe {
 [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
 [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd,int n);
 [DllImport("user32.dll")] public static extern bool SetCursorPos(int X,int Y);
 [DllImport("user32.dll")] public static extern void mouse_event(uint f,uint dx,uint dy,uint data,UIntPtr extra);
}
"@
$edge=Get-Process msedge -ErrorAction SilentlyContinue | Where-Object {$_.MainWindowHandle -ne 0} | Select-Object -First 1
if($null -eq $edge){throw 'No visible Edge window'}
[W32Probe]::ShowWindow($edge.MainWindowHandle,9)|Out-Null
[W32Probe]::SetForegroundWindow($edge.MainWindowHandle)|Out-Null
$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$out=@()
for($i=0;$i -lt $all.Count;$i++){
 $e=$all.Item($i)
 $ct=$e.Current.ControlType.ProgrammaticName
 $name=[string]$e.Current.Name
 if(($ct -match 'Button|Image|Text') -and $name){
   $r=$e.Current.BoundingRectangle
   $out += [pscustomobject]@{
     type=$ct
     name=$name
     aid=[string]$e.Current.AutomationId
     x=[string]$r.X
     y=[string]$r.Y
     w=[string]$r.Width
     h=[string]$r.Height
     enabled=[bool]$e.Current.IsEnabled
   }
   if($out.Count -ge 220){break}
 }
}
[W32Probe]::SetCursorPos(520,620)|Out-Null
[W32Probe]::mouse_event(2,0,0,0,[UIntPtr]::Zero)
[W32Probe]::mouse_event(4,0,0,0,[UIntPtr]::Zero)
Start-Sleep -Milliseconds 250
[System.Windows.Forms.SendKeys]::SendWait('^a')
[System.Windows.Forms.SendKeys]::SendWait('^c')
Start-Sleep -Milliseconds 250
$clip=[string](Get-Clipboard -Raw -ErrorAction SilentlyContinue)
if($clip.Length -gt 18000){$clip=$clip.Substring([Math]::Max(0,$clip.Length-18000))}
[pscustomobject]@{title=$edge.MainWindowTitle;page_text=$clip;controls=$out}|ConvertTo-Json -Depth 6 -Compress
